// Currency metadata: display symbol and number of minor-unit digits (ISO 4217 exponent).
export const CURRENCIES = {
  USD: { symbol: '$', decimals: 2 },
  EUR: { symbol: '€', decimals: 2 },
  GBP: { symbol: '£', decimals: 2 },
  CNY: { symbol: '¥', decimals: 2 },
  JPY: { symbol: '¥', decimals: 0 },
  KRW: { symbol: '₩', decimals: 0 },
  KWD: { symbol: 'KD', decimals: 3 },
};
import { CURRENCIES } from './currencies.js';

function groupThousands(digits) {
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

/**
 * Format an amount expressed in minor units (e.g. cents) for display.
 *
 *   formatMoney(123456, 'USD') // => '$1,234.56'
 */
export function formatMoney(amountMinor, currency) {
  const { symbol } = CURRENCIES[currency];
  const major = amountMinor / 100;
  const [whole, fraction] = major.toFixed(2).split('.');
  return `${symbol}${groupThousands(whole)}.${fraction}`;
}
export { CURRENCIES } from './currencies.js';
export { formatMoney } from './format.js';
import { describe, expect, test } from 'vitest';
import { formatMoney } from '../src/index.js';

describe('formatMoney', () => {
  test('formats cents as dollars', () => {
    expect(formatMoney(1999, 'USD')).toBe('$19.99');
  });

  test('pads the fraction', () => {
    expect(formatMoney(500, 'EUR')).toBe('€5.00');
    expect(formatMoney(7, 'GBP')).toBe('£0.07');
  });

  test('groups thousands', () => {
    expect(formatMoney(123456789, 'USD')).toBe('$1,234,567.89');
  });

  test('formats zero', () => {
    expect(formatMoney(0, 'CNY')).toBe('¥0.00');
  });
});
